export type DetailRoute =
  | { kind: "search" }
  | { kind: "member"; id: string }
  | { kind: "funder"; id: string }
  | { kind: "invalid" };

const funderIdPattern =
  /^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu;
const memberIdPattern = /^[1-9]\d*$/u;

export function readDetailRoute(path: string): DetailRoute {
  if (path === "/") return { kind: "search" };
  const member = /^\/members\/([^/]+)\/?$/u.exec(path);
  if (
    member &&
    memberIdPattern.test(member[1]) &&
    Number(member[1]) <= 2147483647
  )
    return { kind: "member", id: member[1] };
  const funder = /^\/funders\/([^/]+)\/?$/u.exec(path);
  if (funder && funderIdPattern.test(funder[1]))
    return { kind: "funder", id: funder[1] };
  return { kind: "invalid" };
}

export interface MemberProfile {
  id: string;
  name: string;
  partyName: string;
  constituency: string;
  isCurrentCommons: boolean;
}

export interface FundingEntry {
  funder: { id: string; name: string } | null;
  amount: string | null;
  currency: string | null;
  paymentType: string | null;
}

export interface MemberDetails {
  member: MemberProfile;
  declarations: {
    sourceId: number;
    categoryName: string;
    registeredAt: string | null;
    entries: FundingEntry[];
  }[];
  declarationCount: number;
  declarationLimit: number;
}

interface Total {
  amount: string | null;
  entryCount: number;
  unknownAmountCount: number;
}

export interface FunderDetails {
  funder: {
    id: string;
    name: string;
    funderKind: string | null;
    companyNumber: string | null;
  };
  currencies: {
    currency: string;
    parties: (Total & { partyName: string })[];
    topRecipients: (Total & { member: MemberProfile })[];
  }[];
  entryCount: number;
  unknownCurrencyCount: number;
  recipientLimit: number;
}

export type DetailState =
  | { kind: "loading" }
  | { kind: "member"; details: MemberDetails }
  | { kind: "funder"; details: FunderDetails }
  | { kind: "not-found" }
  | { kind: "error"; message: string };

function malformed(): never {
  throw new Error("Details returned an unexpected response. Try again.");
}
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function record(value: unknown): Record<string, unknown> {
  return isRecord(value) ? value : malformed();
}
function text(value: unknown): string {
  return typeof value === "string" ? value : malformed();
}
function nullableText(value: unknown): string | null {
  return value === null ? null : text(value);
}
function count(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
    ? value
    : malformed();
}
function list(value: unknown): unknown[] {
  return Array.isArray(value) ? value : malformed();
}
function decimal(value: unknown): string | null {
  const result = nullableText(value);
  if (result !== null && !/^-?\d+(?:\.\d+)?$/u.test(result)) return malformed();
  return result;
}
function identity(value: unknown, kind: "MP" | "Funder"): string {
  const id = text(value);
  if (
    kind === "MP"
      ? !memberIdPattern.test(id) || Number(id) > 2147483647
      : !funderIdPattern.test(id)
  )
    return malformed();
  return id;
}
function memberProfile(value: unknown): MemberProfile {
  const row = record(value);
  if (typeof row.is_current_commons !== "boolean") return malformed();
  return {
    id: identity(row.id, "MP"),
    name: text(row.name),
    partyName: text(row.party_name),
    constituency: text(row.constituency),
    isCurrentCommons: row.is_current_commons,
  };
}
function readMember(value: unknown): MemberDetails {
  const row = record(value);
  return {
    member: memberProfile(row.member),
    declarationCount: count(row.declaration_count),
    declarationLimit: count(row.declaration_limit),
    declarations: list(row.declarations).map((value) => {
      const declaration = record(value);
      const registeredAt = nullableText(declaration.registered_at);
      if (registeredAt !== null && !Number.isFinite(Date.parse(registeredAt)))
        return malformed();
      return {
        sourceId: count(declaration.source_id),
        categoryName: text(declaration.category_name),
        registeredAt,
        entries: list(declaration.entries).map((value) => {
          const entry = record(value);
          const funder = entry.funder === null ? null : record(entry.funder);
          return {
            funder:
              funder === null
                ? null
                : {
                    id: identity(funder.id, "Funder"),
                    name: text(funder.name),
                  },
            amount: decimal(entry.amount),
            currency: nullableText(entry.currency),
            paymentType: nullableText(entry.payment_type),
          };
        }),
      };
    }),
  };
}
function total(row: Record<string, unknown>): Total {
  return {
    amount: decimal(row.amount),
    entryCount: count(row.entry_count),
    unknownAmountCount: count(row.unknown_amount_count),
  };
}
function readFunder(value: unknown): FunderDetails {
  const row = record(value);
  const funder = record(row.funder);
  return {
    funder: {
      id: identity(funder.id, "Funder"),
      name: text(funder.name),
      funderKind: nullableText(funder.funder_kind),
      companyNumber: nullableText(funder.company_number),
    },
    entryCount: count(row.entry_count),
    unknownCurrencyCount: count(row.unknown_currency_count),
    recipientLimit: count(row.recipient_limit),
    currencies: list(row.currencies).map((value) => {
      const group = record(value);
      const currency = text(group.currency);
      if (!currency.trim()) return malformed();
      return {
        currency,
        parties: list(group.parties).map((value) => {
          const party = record(value);
          return { ...total(party), partyName: text(party.party_name) };
        }),
        topRecipients: list(group.top_recipients).map((value) => {
          const recipient = record(value);
          return {
            ...total(recipient),
            member: memberProfile(recipient.member),
          };
        }),
      };
    }),
  };
}

export async function loadDetails(
  route: Extract<DetailRoute, { kind: "member" | "funder" }>,
  signal: AbortSignal,
): Promise<DetailState> {
  const controller = new AbortController();
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, 10_000);
  try {
    const response = await fetch(
      `/api/${route.kind === "member" ? "members" : "funders"}/${route.id}`,
      { signal: controller.signal },
    );
    if (response.status === 404) return { kind: "not-found" };
    if (!response.ok)
      throw new Error(
        "The details service is unavailable. Try again in a moment.",
      );
    const body: unknown = await response.json();
    const state: DetailState =
      route.kind === "member"
        ? { kind: "member", details: readMember(body) }
        : { kind: "funder", details: readFunder(body) };
    if (
      (state.kind === "member"
        ? state.details.member.id
        : state.details.funder.id
      ).toLowerCase() !== route.id.toLowerCase()
    )
      return malformed();
    return state;
  } catch (error) {
    if (signal.aborted) throw error;
    return {
      kind: "error",
      message: timedOut
        ? "Details are taking too long. Try again."
        : error instanceof Error &&
            !(error instanceof TypeError || error instanceof SyntaxError)
          ? error.message
          : "Couldn’t connect to details. Check your connection and try again.",
    };
  } finally {
    clearTimeout(timer);
    signal.removeEventListener("abort", cancel);
  }
}

export function backToSearch(): string {
  const params = new URLSearchParams(window.location.search);
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  return retained.size ? `/?${retained}` : "/";
}

export function formatAmount(value: string | null): string {
  if (value === null) return "Amount unavailable";
  const negative = value.startsWith("-");
  const unsigned = negative ? value.slice(1) : value;
  const [whole, fraction] = unsigned.split(".");
  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;
}

export function registrationDate(value: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}
// Search defaults live here. The API applies
// max_entries independently to MPs and funders, then merges by similarity.
export const searchConfiguration = {
  minimumCharacters: 3,
  debounceMs: 250,
  maxEntriesPerType: 10,
  strictness: 1,
  timeoutMs: 10_000,
};

export function readStrictness(value: string | null): number {
  if (!value?.trim()) return searchConfiguration.strictness;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 && parsed <= 1
    ? Math.round(parsed * 100) / 100
    : searchConfiguration.strictness;
}

export type Entity =
  | { id: string; name: string; kind: "MP"; funderKind: null }
  | { id: string; name: string; kind: "Funder"; funderKind: string | null };

export function entityHref(entity: Pick<Entity, "kind" | "id">): string {
  const params = new URLSearchParams(window.location.search);
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  const query = retained.size ? `?${retained}` : "";
  return `/${entity.kind === "MP" ? "members" : "funders"}/${encodeURIComponent(entity.id)}${query}`;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function readEntities(body: unknown): Entity[] {
  if (!isRecord(body) || !Array.isArray(body.entities)) {
    throw new Error("Search returned an unexpected response. Try again.");
  }

  return body.entities.map((value: unknown) => {
    if (
      !isRecord(value) ||
      typeof value.name !== "string" ||
      typeof value.id !== "string" ||
      (value.kind !== "MP" && value.kind !== "Funder") ||
      (value.funder_kind !== null && typeof value.funder_kind !== "string")
    ) {
      throw new Error("Search returned an unexpected response. Try again.");
    }
    if (value.kind === "MP") {
      if (
        !/^[1-9]\d*$/u.test(value.id) ||
        Number(value.id) > 2147483647 ||
        value.funder_kind !== null
      )
        throw new Error(
          "Search returned an unexpected MP identity. Try again.",
        );
      return { id: value.id, name: value.name, kind: "MP", funderKind: null };
    }
    if (
      !/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu.test(
        value.id,
      )
    )
      throw new Error(
        "Search returned an unexpected funder identity. Try again.",
      );
    return {
      id: value.id,
      name: value.name,
      kind: "Funder",
      funderKind: value.funder_kind,
    };
  });
}

export async function searchEntities(
  term: string,
  signal: AbortSignal,
  strictness: number,
): Promise<Entity[]> {
  const controller = new AbortController();
  let timedOut = false;
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  const timeout = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, searchConfiguration.timeoutMs);

  try {
    const params = new URLSearchParams({
      term,
      max_entries: String(searchConfiguration.maxEntriesPerType),
      strictness: String(strictness),
    });
    const response = await fetch(`/api/search?${params}`, {
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(
        "The search service is unavailable. Try again in a moment.",
      );
    }
    const body: unknown = await response.json();
    return readEntities(body);
  } catch (error) {
    if (timedOut) throw new Error("Search is taking too long. Try again.");
    if (signal.aborted) throw error;
    if (error instanceof TypeError || error instanceof SyntaxError) {
      throw new Error(
        "Couldn’t connect to search. Check your connection and try again.",
      );
    }
    throw error;
  } finally {
    clearTimeout(timeout);
    signal.removeEventListener("abort", cancel);
  }
}

export function entityType(entity: Entity): string {
  if (entity.kind === "MP") return "MP";
  return `Funder: ${funderKindLabel(entity.funderKind)}`;
}

export function funderKindLabel(value: string | null): string {
  const kind = value?.trim();
  if (!kind || kind.toLowerCase() === "not specified") return "Unclassified";
  if (kind.toLowerCase() === "individual") return "Individual";
  if (kind.toLowerCase() === "company") return "Company";
  if (kind.toLowerCase() === "trade union") return "Trade union";
  return kind;
}

export function funderKindIcon(value: string | null) {
  switch (funderKindLabel(value).toLowerCase()) {
    case "individual":
      return "person";
    case "company":
      return "building";
    case "trade union":
      return "group";
    case "unclassified":
      return "question";
    default:
      return "tag";
  }
}

// Plain-text segments keep source names intact and never interpret names or
// user input as markup. Matching here only highlights; it never changes rank.
export function highlightName(name: string, term: string) {
  const tokens = [...new Set(term.trim().split(/\s+/u).filter(Boolean))]
    .sort((a, b) => b.length - a.length)
    .map((token) => token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  if (!tokens.length) return [{ text: name, matched: false }];
  const pattern = new RegExp(tokens.join("|"), "giu");
  const segments: { text: string; matched: boolean }[] = [];
  let position = 0;
  for (const match of name.matchAll(pattern)) {
    const start = match.index;
    if (start > position)
      segments.push({ text: name.slice(position, start), matched: false });
    segments.push({ text: match[0], matched: true });
    position = start + match[0].length;
  }
  if (position < name.length)
    segments.push({ text: name.slice(position), matched: false });
  return segments;
}
<script lang="ts">
  import Icon from "./lib/Icon.svelte";
  import EntityIndicator from "./lib/EntityIndicator.svelte";
  import {
    entityHref,
    highlightName,
    readStrictness,
    searchConfiguration,
    searchEntities,
    type Entity,
  } from "./lib/search";

  type SearchState =
    | { status: "idle" }
    | { status: "loading"; term: string }
    | { status: "success"; term: string; entities: Entity[] }
    | { status: "error"; term: string; message: string };

  let query = $state(new URL(window.location.href).searchParams.get("q") ?? "");
  let strictness = $state(
    readStrictness(
      new URL(window.location.href).searchParams.get("strictness"),
    ),
  );
  let composing = $state(false);
  let attempt = $state(0);
  let input: HTMLInputElement;
  let searchState = $state<SearchState>({ status: "idle" });
  const term = $derived(query.trim());
  const charactersNeeded = $derived(
    Math.max(0, searchConfiguration.minimumCharacters - [...term].length),
  );
  const announcement = $derived(
    searchState.status === "loading"
      ? "Searching…"
      : searchState.status === "success"
        ? `${searchState.entities.length} ${searchState.entities.length === 1 ? "result" : "results"} shown for ${searchState.term}.`
        : "",
  );

  $effect(() => {
    const currentTerm = term;
    const currentStrictness = strictness;
    const currentAttempt = attempt;
    if (
      composing ||
      [...currentTerm].length < searchConfiguration.minimumCharacters
    ) {
      searchState = { status: "idle" };
      return;
    }

    const controller = new AbortController();
    let current = true;
    searchState = { status: "loading", term: currentTerm };
    const timer = setTimeout(
      async () => {
        try {
          const entities = await searchEntities(
            currentTerm,
            controller.signal,
            currentStrictness,
          );
          if (current)
            searchState = { status: "success", term: currentTerm, entities };
        } catch (error) {
          if (current)
            searchState = {
              status: "error",
              term: currentTerm,
              message:
                error instanceof Error
                  ? error.message
                  : "Search couldn’t load. Try again.",
            };
        }
      },
      currentAttempt > 0 ? 0 : searchConfiguration.debounceMs,
    );

    return () => {
      current = false;
      clearTimeout(timer);
      controller.abort();
    };
  });

  function updateQuery(value: string) {
    attempt = 0;
    query = value;
    const url = new URL(window.location.href);
    if (value.trim()) url.searchParams.set("q", value.trim());
    else url.searchParams.delete("q");
    window.history.replaceState(null, "", url);
  }

  function updateStrictness(value: string) {
    attempt = 0;
    strictness = readStrictness(value);
    const url = new URL(window.location.href);
    url.searchParams.set("strictness", String(strictness));
    window.history.replaceState(null, "", url);
  }

  function clearSearch() {
    updateQuery("");
    input.focus();
  }

  function shortcut(event: KeyboardEvent) {
    const target = event.target;
    const editing =
      target instanceof HTMLElement &&
      (target.isContentEditable ||
        ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));
    if (
      event.key === "/" &&
      !editing &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey
    ) {
      event.preventDefault();
      input.focus();
    }
    if (event.key === "Escape" && target === input && !event.isComposing)
      clearSearch();
  }

  function atLimit(entities: Entity[]) {
    return ["MP", "Funder"].some(
      (kind) =>
        entities.filter((entity) => entity.kind === kind).length >=
        searchConfiguration.maxEntriesPerType,
    );
  }
</script>

<svelte:window
